import{_ as i,o as a,c as n,a2 as e}from"./chunks/framework.CjPXnAcb.js";const c=JSON.parse('{"title":"Markdown —— 用纯文本写排版","description":"","frontmatter":{"title":"Markdown —— 用纯文本写排版"},"headers":[],"relativePath":"prereq/04-markdown.md","filePath":"prereq/04-markdown.md","lastUpdated":1789060104000}'),t={name:"prereq/04-markdown.md"};function l(o,s,d,p,h,r){return a(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="_04-·-markdown-为什么全世界写文档都用它" tabindex="-1">04 · Markdown：为什么全世界写文档都用它 <a class="header-anchor" href="#_04-·-markdown-为什么全世界写文档都用它" aria-label="Permalink to &quot;04 · Markdown：为什么全世界写文档都用它&quot;">​</a></h1><blockquote><p>一句话说清这课解决什么问题：让你看懂并能亲手写出 Wiki 页面里那些 <code>#</code>、<code>**</code>、<code>-</code> 符号——你正在写的整个网站，本质就是一堆这样的文本文件。</p></blockquote><h2 id="它是什么-大白话-生活比喻" tabindex="-1">它是什么？（大白话 + 生活比喻） <a class="header-anchor" href="#它是什么-大白话-生活比喻" aria-label="Permalink to &quot;它是什么？（大白话 + 生活比喻）&quot;">​</a></h2><p><strong>Markdown</strong> 是一种「用纯文本符号来表示排版」的写作格式。它不是软件，而是一套约定：你写下某些符号，阅读工具（比如你的 VitePress 网站）就会把它们变成漂亮的排版效果。</p><p>生活比喻：Markdown 就像发微信时的「暗号」。你给朋友发一句「我今天 <strong>特别</strong> 开心」，那两颗星在聊天框里就是两颗星，但很多软件会默契地把 <code>**特别**</code> 显示成<strong>加粗</strong>。你只管按暗号写字，显示效果由软件负责——这就是 Markdown 的全部思想。</p><p>几个最常用的暗号：</p><ul><li><code>#</code> 开头的行 → 大标题（<code>##</code> 是二级标题，以此类推）</li><li><code>**文字**</code> → 加粗，<code>*文字*</code> → 斜体</li><li><code>- </code> 开头的行 → 无序列表（就是前面带圆点的列表）</li></ul><h2 id="为什么我们需要它" tabindex="-1">为什么我们需要它？ <a class="header-anchor" href="#为什么我们需要它" aria-label="Permalink to &quot;为什么我们需要它？&quot;">​</a></h2><p>想想你正在做的事：</p><ol><li><strong>你的 Wiki 就是一堆 <code>.md</code> 文件</strong>。VitePress 不需要你去点鼠标排版，它读这些文本文件，直接变成 <a href="https://jlshdsdk.github.io/my-wiki/" target="_blank" rel="noreferrer">https://jlshdsdk.github.io/my-wiki/</a> 上的漂亮网页。</li><li><strong>纯文本永远打得开</strong>。Word 文档换个软件可能乱码，而 <code>.md</code> 用记事本就能打开，再过二十年也一样。</li><li><strong>Git 能看清你每次改了哪一行</strong>。以后你把 Wiki 推到 GitHub（你的用户名是 jlshdsdk），每次修改都能精确显示「第几行从什么改成了什么」。如果是 Word 的二进制文件，Git 根本看不懂。</li></ol><p>也就是说：Markdown 是「人好写、机器好读、版本管理好对比」的三赢格式，所以全世界的笔记、文档、README 都用它。</p><h2 id="动手试一试" tabindex="-1">动手试一试 <a class="header-anchor" href="#动手试一试" aria-label="Permalink to &quot;动手试一试&quot;">​</a></h2><p>下面是一段自我介绍，我们逐句给它加上 Markdown 语法（新建一个 <code>test.md</code>，抄进去，然后拖进 VS Code 预览）：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 关于我</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我是 </span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**jlshdsdk**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">，正在从零学 </span><span style="--shiki-light:#24292E;--shiki-light-font-style:italic;--shiki-dark:#E1E4E8;--shiki-dark-font-style:italic;">*大模型应用开发*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">。</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 平时用 Windows 11 写笔记</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 目标是做一个自己的知识库网站</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我的 Wiki 在这里：[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">我的 Wiki</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">https://jlshdsdk.github.io/my-wiki/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\`\`\`python</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hello, Markdown!&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\`\`\`</span></span></code></pre></div><p>逐句解释：</p><ul><li><code>## 关于我</code> → 二级标题，页面上会显示为大字。</li><li><code>**jlshdsdk**</code> → 加粗；<code>*大模型应用开发*</code> → 单星是斜体，注意区别。</li><li><code>- 平时用……</code> → 两行列表，渲染后前面会有圆点。</li><li><code>[我的 Wiki](网址)</code> → 方括号写显示文字，圆括号放链接地址，合起来是超链接。</li><li>最后那对三个反引号包住的是<strong>代码块</strong>，开头反引号后面写 <code>python</code>，还能自动语法高亮。</li></ul><p>图片写法也顺手记住：<code>![图片说明](图片网址)</code>，比链接多一个开头的感叹号。表格的写法：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 语法 | 效果   |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| ---- | ------ |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| </span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**x**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 加粗   |</span></span></code></pre></div><h3 id="vitepress-的扩展-容器语法" tabindex="-1">VitePress 的扩展：容器语法 <a class="header-anchor" href="#vitepress-的扩展-容器语法" aria-label="Permalink to &quot;VitePress 的扩展：容器语法&quot;">​</a></h3><p>你的站点是 VitePress，它在标准 Markdown 之上加了几种「提示盒子」，写法是三个冒号：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::: tip 小提示</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">这里写提示内容，会渲染成一个绿色提示框。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:::</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::: warning 注意</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">这是黄色警告框。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:::</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::: details 点我看答案</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">这是可折叠的内容，点标题才展开。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:::</span></span></code></pre></div><h3 id="frontmatter-文件最上面的「档案卡」" tabindex="-1">frontmatter：文件最上面的「档案卡」 <a class="header-anchor" href="#frontmatter-文件最上面的「档案卡」" aria-label="Permalink to &quot;frontmatter：文件最上面的「档案卡」&quot;">​</a></h3><p>你可能注意到本文件开头有两行 <code>---</code>，中间夹着 <code>title: ...</code>。这叫 <strong>frontmatter</strong>——文件最顶部两条三横线之间放的「元信息」（关于这个文件的信息，而不是正文）。VitePress 会读它来设置页面标题、侧边栏顺序等。记住：frontmatter 必须是文件的第一行就开始，不能前面有空内容。</p><h2 id="常见报错与怎么读它" tabindex="-1">常见报错与怎么读它 <a class="header-anchor" href="#常见报错与怎么读它" aria-label="Permalink to &quot;常见报错与怎么读它&quot;">​</a></h2><p>Markdown 没有编译器，不会弹红色报错，但有一种极常见的「排版事故」——<strong>代码块没闭合</strong>。假设你写了：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\`\`\`python</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;hello&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\`\`\`</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">上面忘了写结尾的 \`\`\`（或者结尾多打了一个），从这行往后……</span></span></code></pre></div><p>如果你写了开头三个反引号 <code>\`\`\`</code>，却忘了写结尾三个，那么 Markdown 会认为「从这行开始全是代码」，于是后面<strong>整页的文字都变成等宽字体的灰色代码块</strong>，标题、加粗全部失效，页面排版全乱。</p><p>怎么从「渲染结果怪异」倒推原因？按这三步排查：</p><ol><li><strong>找到排版开始变怪的那个位置</strong>——从哪一行开始不对劲？</li><li><strong>看那一行的上方</strong>，找配对符号：三个反引号是不是只有开头没有结尾？<code>**</code> 是不是只有一半？表格的 <code>|</code> 是不是漏了分隔行？</li><li><strong>记住「符号要成对」</strong>：<code>\`\`\`</code>、<code>**</code>、<code>:::</code> 这些都是开门要关门。逐个检查，几乎百发百中。</li></ol><p>排查小技巧：在 VS Code 里按 <code>Ctrl+Shift+V</code> 打开预览，一边改一边看，乱掉的范围就是你的「案发现场」。</p><h2 id="自测两题" tabindex="-1">自测两题 <a class="header-anchor" href="#自测两题" aria-label="Permalink to &quot;自测两题&quot;">​</a></h2><p><strong>第 1 题</strong>：想把一句话里某个词加粗并且变成可点击的链接，符号该怎么组合？</p><details class="details custom-block"><summary>点击看答案</summary><p>加粗套在链接文字外面：<code>[**加粗的链接**](https:// example.com)</code>（实际使用时网址里不要有空格）。核心思路是 Markdown 语法可以嵌套：<code>[显示文字](网址)</code> 里的「显示文字」部分再用 <code>**</code> 包起来即可。</p></details><p><strong>第 2 题</strong>：你的页面从中间某处开始全部变成了灰色等宽字体，正文排版全没了，最可能的原因是什么？</p><details class="details custom-block"><summary>点击看答案</summary><p>某个代码块的结尾三个反引号 <code>\`\`\`</code> 丢了（或者数量不配对），导致 Markdown 认为后面全是代码。定位方法：从排版开始乱的那行往上找，找到最近一个代码块开头，补上成对的结尾即可。</p></details><h2 id="下一课" tabindex="-1">下一课 <a class="header-anchor" href="#下一课" aria-label="Permalink to &quot;下一课&quot;">​</a></h2><p>你已经会写网站的内容了。下一课讲 <strong>HTTP 与 API</strong>——搞清楚「浏览器和服务器怎么对话」「调用大模型的 API 到底是怎么回事」，这是你后面调智谱 GLM 接口的地基。</p>`,37)])])}const E=i(t,[["render",l]]);export{c as __pageData,E as default};
